### 2.2 `harness.js` — 5 scenarios, traces and invariant assertions

```js
'use strict';
/*
 * harness.js
 * -------------------------------------------------------------------------
 * Scenario harness for the RFC 6675 + CUBIC simulator.  Replays at least five
 * scenarios (single loss, burst loss, heavy reordering, ACK loss, pure RTO),
 * emits cwnd / ssthresh / pipe traces, and asserts the four invariants.
 *
 * Run:  node harness.js
 * -------------------------------------------------------------------------
 */

const { TcpSim } = require('./rfc6675');

const BETA = 0.7;

const SCENARIOS = {
  'single-loss': {
    label: 'single-loss',
    seed: 1,
    nSegments: 40,
    initialCwndSegs: 10,
    dropFirst: [10],
    baseDelay: 10,
  },
  'burst-loss': {
    label: 'burst-loss',
    seed: 2,
    nSegments: 40,
    initialCwndSegs: 10,
    dropFirst: [12, 13, 14, 15],
    baseDelay: 10,
  },
  'heavy-reordering': {
    label: 'heavy-reordering',
    seed: 3,
    nSegments: 45,
    initialCwndSegs: 10,
    reorderFirst: [3, 4, 5, 6, 7, 8],
    reorderDelay: 120,
    baseDelay: 10,
  },
  'ack-loss': {
    label: 'ack-loss',
    seed: 4,
    nSegments: 45,
    initialCwndSegs: 10,
    dropFirst: [8, 22],
    ackLossProb: 0.2,
    baseDelay: 10,
  },
  'pure-rto': {
    label: 'pure-rto',
    seed: 5,
    nSegments: 12,
    initialCwndSegs: 1,
    dropFirst: [0],
    baseDelay: 10,
    baseRto: 200,
  },
};

/* ------------------------------- assertions ----------------------------- */
function checkInvariants(res) {
  const checks = [];
  const v = res.violations;
  const startsWith = (p) => v.filter((x) => x.msg.startsWith(p));

  /* I1: never retransmit data that is still counted as outstanding */
  const i1 = startsWith('RETRANSMIT_OUTSTANDING');
  checks.push({
    id: 'I1',
    name: 'nothing retransmitted while still marked outstanding',
    pass: i1.length === 0,
    detail: i1.length === 0 ? 'all loss retransmissions target lost segments'
      : i1.map((x) => x.msg).join('; '),
  });

  /* I2: pipe never negative */
  const i2 = startsWith('PIPE_NEGATIVE');
  checks.push({
    id: 'I2',
    name: 'pipe never goes negative',
    pass: i2.length === 0 && res.minPipe >= 0,
    detail: `min(pipe)=${res.minPipe}`,
  });

  /* I3: spurious fast retransmit must not collapse cwnd repeatedly.
   * Count cwnd reduction events and verify every one is either a recovery
   * entry (one reduction) or an RTO (legitimate). */
  const reductions = [];
  const tr = res.trace;
  for (let i = 1; i < tr.length; i++) {
    if (tr[i].cwnd < tr[i - 1].cwnd - 1e-9) {
      reductions.push({
        t: tr[i].t,
        event: tr[i].event,
        from: tr[i - 1].cwnd,
        to: tr[i].cwnd,
      });
    }
  }
  const badReductions = reductions.filter(
    (r) => r.event !== 'enterRecovery' && r.event !== 'rto',
  );
  /* For every recovery episode, cwnd must never fall below the single reduced
   * value (no repeated collapse) until the episode ends (exit or RTO). */
  let localCollapse = 0;
  for (const e of res.enterEvents) {
    const startIdx = tr.findIndex(
      (r) =>
        r.event === 'enterRecovery' &&
        Math.abs(r.cwnd - e.reducedTo) < 1e-9 &&
        r.t === e.t,
    );
    if (startIdx < 0) continue;
    for (let j = startIdx; j < tr.length; j++) {
      if (tr[j].event === 'exitRecovery' || tr[j].event === 'rto') break;
      if (tr[j].cwnd < e.reducedTo - 1e-9) {
        localCollapse++;
        break;
      }
    }
  }
  const perEpisodeOk =
    reductions.length <= res.enterEvents.length + res.stats.rtoCount;
  checks.push({
    id: 'I3',
    name: 'spurious fast retransmit resolves without collapsing cwnd',
    pass: badReductions.length === 0 && localCollapse === 0 && perEpisodeOk,
    detail:
      `reductions=${reductions.length} (fast-entries=${res.enterEvents.length}, ` +
      `rto=${res.stats.rtoCount}); spurious_rxt=${res.stats.spuriousRetransmissions}; ` +
      `bad=${badReductions.map((r) => r.event).join(',') || 'none'}; ` +
      `local_collapse=${localCollapse}`,
  });

  /* I4: recovery exits only once all pre-recovery data is SACKed */
  const i4 = v.filter((x) => x.msg.startsWith('EXIT_BEFORE'));
  checks.push({
    id: 'I4',
    name: 'recovery exits only once all pre-recovery data is SACKed',
    pass: i4.length === 0,
    detail: i4.length === 0 ? `${res.recoveryExits} clean recovery exit(s)`
      : i4.map((x) => x.msg).join('; '),
  });

  /* sanity / completion */
  const misc = v.filter(
    (x) =>
      x.msg.startsWith('NEW_DATA_OUT_OF_ORDER') ||
      x.msg.startsWith('MAX_EVENTS'),
  );
  checks.push({
    id: 'I5',
    name: 'transfer completes and receiver reconstructs all data',
    pass: !res.stalled && res.receiverNext === res.cfgN && misc.length === 0,
    detail: `receiverNext=${res.receiverNext}/${res.cfgN} stalled=${res.stalled}`,
  });

  return checks;
}

/* ------------------------------- reporting ------------------------------ */
function fmt(n) {
  return n === null || n === undefined ? '-' : String(Math.round(n));
}

function pad(s, w) {
  s = String(s);
  return s.length >= w ? s : s + ' '.repeat(w - s.length);
}

function printTrace(res, maxRows = 60) {
  const keep = new Set([
    'start',
    'txNew',
    'rxt',
    'enterRecovery',
    'exitRecovery',
    'rto',
    'dataDrop',
    'end',
  ]);
  const rows = res.trace.filter(
    (r) => keep.has(r.event) || (r.event === 'ack' && r.adv),
  );
  console.log(
    `  ${pad('t(ms)', 9)}${pad('event', 15)}${pad('cwnd', 8)}${pad('ssthresh', 9)}` +
      `${pad('pipe', 7)}${pad('sndUna', 8)}${pad('sndNxt', 8)}${pad('recov', 6)}`,
  );
  const shown = rows.length > maxRows
    ? rows.slice(0, maxRows / 2).concat([{ event: '...', t: '...' }], rows.slice(-maxRows / 2))
    : rows;
  for (const r of shown) {
    if (r.event === '...') {
      console.log('  ...');
      continue;
    }
    console.log(
      '  ' +
        pad(r.t, 9) +
        pad(r.event, 15) +
        pad(fmt(r.cwnd), 8) +
        pad(fmt(r.ssthresh), 9) +
        pad(fmt(r.pipe), 7) +
        pad(fmt(r.sndUna), 8) +
        pad(fmt(r.sndNxt), 8) +
        pad(r.inRecovery ? 'yes' : 'no', 6),
    );
  }
}

/* --------------------------------- main --------------------------------- */
function runAll() {
  let allPass = true;
  const summary = [];
  for (const key of Object.keys(SCENARIOS)) {
    const cfg = SCENARIOS[key];
    const sim = new TcpSim(cfg);
    const res = sim.run();
    res.cfgN = cfg.nSegments;
    const checks = checkInvariants(res);
    const pass = checks.every((c) => c.pass);
    allPass = allPass && pass;

    console.log('\n' + '='.repeat(78));
    console.log(`SCENARIO: ${res.label}`);
    console.log('='.repeat(78));
    console.log(
      `  sent=${res.stats.dataSent} dropped=${res.stats.dataDropped} ` +
        `reordered=${res.stats.reordered} acksSent=${res.stats.acksSent} ` +
        `acksDropped=${res.stats.acksDropped}`,
    );
    console.log(
      `  rto=${res.stats.rtoCount} retransmissions=${res.stats.retransmissions} ` +
        `spurious=${res.stats.spuriousRetransmissions} ` +
        `recoveryEpisodes=${res.recoveryEpisodes} exits=${res.recoveryExits} ` +
        `cwndReductions=${res.cwndReductions}`,
    );
    printTrace(res);
    console.log('  invariants:');
    for (const c of checks) {
      console.log(`    [${c.pass ? 'PASS' : 'FAIL'}] ${c.id} ${c.name} -- ${c.detail}`);
    }
    summary.push({ key, pass, res, checks });
  }

  console.log('\n' + '='.repeat(78));
  console.log('SUMMARY');
  console.log('='.repeat(78));
  for (const s of summary) {
    console.log(`  ${s.pass ? 'PASS' : 'FAIL'}  ${s.key}`);
  }
  console.log(allPass ? '\nALL SCENARIOS PASSED' : '\nSOME SCENARIOS FAILED');
  return { allPass, summary };
}

if (require.main === module) {
  const { allPass } = runAll();
  process.exit(allPass ? 0 : 1);
}

module.exports = { SCENARIOS, checkInvariants, runAll };
