### 2.3 `verify.js` — fault injection proving the checks are not vacuous

```js
'use strict';
/*
 * verify.js
 * -------------------------------------------------------------------------
 * Two-part verification:
 *   (A) every baseline scenario passes all four invariants;
 *   (B) deliberate fault injection makes the corresponding invariant fail,
 *       proving the checker is not vacuous.
 *
 * Run: node verify.js
 * -------------------------------------------------------------------------
 */

const { TcpSim } = require('./rfc6675');
const { SCENARIOS, checkInvariants } = require('./harness');

function run(cfg) {
  const sim = new TcpSim(cfg);
  const res = sim.run();
  res.cfgN = cfg.nSegments;
  return res;
}

function failedIds(res) {
  return checkInvariants(res)
    .filter((c) => !c.pass)
    .map((c) => c.id);
}

const results = [];

/* (A) baselines must pass */
for (const key of Object.keys(SCENARIOS)) {
  const fails = failedIds(run(SCENARIOS[key]));
  results.push({
    name: `baseline ${key}`,
    expectation: 'all invariants pass',
    ok: fails.length === 0,
    detail: fails.length ? `failed: ${fails.join(',')}` : 'ok',
  });
}

/* (B) fault injection must be caught by the expected invariant */
const mutations = [
  { flag: 'bugRetransmitOutstanding', expect: 'I1' },
  { flag: 'bugNegativePipe', expect: 'I2' },
  { flag: 'bugRepeatedCollapse', expect: 'I3' },
  { flag: 'bugEarlyExit', expect: 'I4' },
];
for (const m of mutations) {
  const caught = [];
  for (const key of Object.keys(SCENARIOS)) {
    const cfg = Object.assign({}, SCENARIOS[key], {
      [m.flag]: true,
      label: `mut:${m.flag}:${key}`,
    });
    const fails = failedIds(run(cfg));
    if (fails.includes(m.expect)) caught.push(key);
  }
  results.push({
    name: `fault-injection ${m.flag}`,
    expectation: `checker reports ${m.expect} in >=1 scenario`,
    ok: caught.length > 0,
    detail: caught.length ? `reported ${m.expect} in: ${caught.join(', ')}` : 'NOT CAUGHT',
  });
}

let allOk = true;
console.log('verification report');
console.log('='.repeat(70));
for (const r of results) {
  allOk = allOk && r.ok;
  console.log(
    `[${r.ok ? 'OK  ' : 'BAD '}] ${r.name}\n         expected: ${r.expectation}\n         ${r.detail}`,
  );
}
console.log('='.repeat(70));
console.log(allOk ? 'VERIFICATION PASSED' : 'VERIFICATION FAILED');
process.exit(allOk ? 0 : 1);
